function validate([matrix]) {
  const n = matrix.length;
  if (n < 1 || n > 100) return 'matrix needs 1 to 100 rows.';
  if (matrix.some(row => !Array.isArray(row) || row.length !== n)) return 'matrix must be square: every row has n values.';
  if (matrix.some(row => row.some(v => !Number.isInteger(v) || v < 1 || v > n))) return 'Each value is an integer from 1 to n.';
  return null;
}

