    const rowSeen = new Set();
    const colSeen = new Set();
    for (let j = 0; j < n; j++) {
      rowSeen.add(matrix[i][j]);
      colSeen.add(matrix[j][i]);
    }
    if (rowSeen.size !== n || colSeen.size !== n) {
      return false;
    }
  }
