function checkValid(matrix) {
  const n = matrix.length;
  for (let r = 0; r < n; r++) {
    const column = matrix.map(row => row[r]);
    for (let v = 1; v <= n; v++) {
      if (!matrix[r].includes(v) || !column.includes(v)) return false;
    }
  }
  return true;
}

