function generate(rand, size) {
  const n = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const shuffle = list => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  const order = () => shuffle(Array.from({ length: n }, (_, i) => i));
  const mode = Math.floor(rand() * 4);
  if (mode === 3) {
    // Every row is a permutation on its own, but the columns are left to chance.
    return [Array.from({ length: n }, () => shuffle(Array.from({ length: n }, (_, i) => i + 1)))];
  }
  // A shuffled Latin square: cyclic rows, then rows, columns and symbols permuted.
  const rows = order();
  const cols = order();
  const symbols = order();
  const matrix = rows.map(r => cols.map(c => symbols[(r + c) % n] + 1));
  if (mode === 1 && n > 1) {
    const r = Math.floor(rand() * n);
    const c = Math.floor(rand() * n);
    matrix[r][c] = (matrix[r][c] % n) + 1;
  }
  if (mode === 2 && n > 1) {
    // Copy one row over another: rows stay valid, columns break.
    const from = Math.floor(rand() * n);
    const to = (from + 1 + Math.floor(rand() * (n - 1))) % n;
    matrix[to] = matrix[from].slice();
  }
  return [matrix];
}
